const err = $input.item.json;
const workflowName = (err.workflow && err.workflow.name) || 'Unknown workflow';
const workflowId = (err.workflow && err.workflow.id) || '';
const nodeName = (err.execution && err.execution.lastNodeExecuted) || 'Unknown node';
const executionUrl = (err.execution && err.execution.url) || '';
const errorObj = (err.execution && err.execution.error) || {};
const errorMessage = errorObj.message || errorObj.description || JSON.stringify(errorObj) || 'No error message available';
const occurredAt = new Date().toUTCString();

const escapeHtml = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const emailHtml = `
<div style="font-family: -apple-system, Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e5e5e5; border-radius: 10px; overflow: hidden;">
  <div style="background: #8C1C1C; color: #ffffff; padding: 18px 24px;">
    <span style="font-size: 13px; letter-spacing: 0.5px; opacity: 0.85;">GRANDVIEW HOTEL SYSTEM</span>
    <h2 style="margin: 4px 0 0; font-size: 18px; font-weight: 600;">Workflow Error Detected</h2>
  </div>
  <div style="padding: 22px 24px 8px;">
    <span style="display: inline-block; padding: 4px 12px; border-radius: 999px; font-size: 11px; font-weight: 700; letter-spacing: 0.5px; color: #ffffff; background: #8C1C1C;">ERROR</span>
    <table style="width: 100%; margin-top: 18px; border-collapse: collapse; font-size: 14px;">
      <tr>
        <td style="padding: 7px 0; color: #888888; width: 120px; vertical-align: top;">Workflow</td>
        <td style="padding: 7px 0; font-weight: 600; color: #1A2B4C;">${escapeHtml(workflowName)}</td>
      </tr>
      <tr>
        <td style="padding: 7px 0; color: #888888; vertical-align: top;">Failed Node</td>
        <td style="padding: 7px 0; color: #222222;">${escapeHtml(nodeName)}</td>
      </tr>
      <tr>
        <td style="padding: 7px 0; color: #888888; vertical-align: top;">Occurred</td>
        <td style="padding: 7px 0; color: #222222;">${escapeHtml(occurredAt)}</td>
      </tr>
    </table>
    <div style="margin-top: 18px; padding: 14px 16px; background: #FBEEEE; border-left: 3px solid #8C1C1C; border-radius: 6px;">
      <div style="font-size: 11px; color: #999999; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 6px;">Error Message</div>
      <div style="font-size: 14px; color: #222222; white-space: pre-wrap; line-height: 1.5; font-family: monospace;">${escapeHtml(errorMessage)}</div>
    </div>
    ${executionUrl ? `<div style="margin-top: 16px;"><a href="${executionUrl}" style="color: #1A2B4C; font-size: 13px;">View full execution &rarr;</a></div>` : ''}
  </div>
  <div style="padding: 14px 24px; margin-top: 10px; background: #FAFAFA; border-top: 1px solid #EFEFEF; font-size: 12px; color: #999999;">
    Logged automatically by the Grandview Hotel error monitor.
  </div>
</div>`;

return [{
  json: {
    workflow_name: workflowName,
    workflow_id: workflowId,
    node_name: nodeName,
    error_message: errorMessage,
    execution_url: executionUrl,
    email_html: emailHtml
  }
}];
